theory.configuration:
# ModSecurity OWASP CRS configuration
SecRuleEngine On

# Include OWASP CRS
Include /etc/modsecurity/crs/crs-setup.conf
Include /etc/modsecurity/crs/rules/*.conf

# Custom rule: Block requests with suspicious parameters
SecRule ARGS "@detectSQLi" \
  "id:1000,\
  phase:2,\
  deny,\
  status:403,\
  log,\
  msg:'SQL Injection detected'"

# Rate limiting rule
SecRule IP:REQUEST_RATE "@gt 100" \
  "id:2000,\
  phase:5,\
  deny,\
  status:429,\
  log,\
  msg:'Rate limit exceeded'"

# AWS WAF (via Terraform)
resource "aws_wafv2_web_acl" "main" {
  name        = "web-acl"
  scope       = "REGIONAL"
  default_action {
    allow {}
  }
  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 0
    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }
    override_action {
      count {}  # Start in count mode
    }
    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSCommonRules"
      sampled_requests_enabled   = true
    }
  }
}

# DNSSEC zone signing (BIND)
dnssec-enable yes;
dnssec-validation yes;

zone "example.com" {
  type master;
  file "example.com.signed";
  auto-dnssec maintain;
  inline-signing yes;
  key-directory "/etc/bind/keys";
};

# DNS filtering with Unbound
server:
  # Block known malware domains
  local-zone: "evil.com" redirect
  local-data: "evil.com A 127.0.0.1"

  # Use Quad9 (9.9.9.9) for threat blocking
  forward-zone:
    name: "."
    forward-addr: 9.9.9.9

# DNS Response Rate Limiting (BIND)
options {
  rate-limit {
    responses-per-second 5;
    window 5;
    slip 2;
  };
};

# DNS monitoring with Zeek/Bro
# Zeek will log all DNS queries to dns.log
# Install Zeek and configure to listen on port 53

# Nginx TLS configuration (Mozilla Intermediate)
server {
    listen 443 ssl http2;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384;
    ssl_prefer_server_ciphers on;
    ssl_ecdh_curve X25519:prime256v1:secp384r1;
    ssl_session_timeout 1d;
    ssl_session_cache shared:MozSSL:10m;
    ssl_session_tickets off;

    # HSTS (31536000 seconds = 1 year)
    add_header Strict-Transport-Security "max-age=63072000" always;

    # OCSP Stapling
    ssl_stapling on;
    ssl_stapling_verify on;
    resolver 1.1.1.1 8.8.8.8;
}

# Test with
curl https://ssllabs.com/ssltest/analyze.html?d=example.com

# testssl.sh CLI test
testssl.sh example.com:443
